INSERT INTO `chips_vendor_communication` (`messageid`, `fromuserid`, `touserid`, `message`, `attachment`, `sent_on`, `isviewed`, `sentby`, `viewedby`, `viewedon`) VALUES
(1, 1, 20, 'With reference to EoI No. EoI/DMFT/BALODABAZARCSF/PMU/2026 for “Setting up of Project Management Unit (PMU) for District Mineral Foundation Trust (DMFT), Baloda Bazar-Bhatapara District,” it is to inform that the Department, DMFT Baloda Bazar-Bhatapara, has scheduled the presentation and interview as per the details below:\n\nDate: 20.03.2026\nTime: 11:00 AM\nMode: Offline\nVenue: Office of Collector & District Magistrate, District Composite Building, Collectorate, Panchsheel Nagar, Balodabazar-Bhatapara (C.G.) - 493332\n\nThe firm is requested to attend the presentation and interview as per the above schedule.', NULL, '2026-03-19 10:38:02', 1, 'CHiPS', 20, '2026-03-24 10:42:04'),
(2, 1, 19, 'With reference to EoI No. EoI/DMFT/BALODABAZARCSF/PMU/2026 for “Setting up of Project Management Unit (PMU) for District Mineral Foundation Trust (DMFT), Baloda Bazar-Bhatapara District,” it is to inform that the Department, DMFT Baloda Bazar-Bhatapara, has scheduled the presentation and interview as per the details below:\r\n\r\nDate: 20.03.2026\r\nTime: 11:00 AM\r\nMode: Offline\r\nVenue: Office of Collector & District Magistrate, District Composite Building, Collectorate, Panchsheel Nagar, Balodabazar-Bhatapara (C.G.) - 493332\r\n\r\nThe firm is requested to attend the presentation and interview as per the above schedule.', NULL, '2026-03-19 10:38:31', 1, 'CHiPS', 19, '2026-03-24 15:10:50'),
(3, 1, 18, 'Message from Admin.', NULL, '2026-04-04 19:59:10', 1, 'CHiPS', 18, '2026-04-04 20:00:01'),
(4, 1, 11, 'Pre-bid query responses for EoI Ref. No. EoI/EMPL/CSF/GG/DA/2026, as shared by the Department, are available under the Published EoI section.', NULL, '2026-04-04 20:25:34', 1, 'CHiPS', 11, '2026-04-08 13:35:28'),
(5, 1, 17, 'Pre-bid query responses for EoI Ref. No. EoI/EMPL/CSF/GG/DA/2026, as shared by the Department, are available under the Published EoI section.', NULL, '2026-04-04 20:25:50', 1, 'CHiPS', 17, '2026-04-04 20:27:44'),
(6, 1, 17, 'Pre-bid query responses for EoI Ref. No. EoI/EMPL/CSF/GG/TPA/2026, as shared by the Department, are available under the Published EoI section.', NULL, '2026-04-04 20:26:47', 1, 'CHiPS', 17, '2026-04-04 20:27:44'),
(7, 1, 17, 'Kindly verify the same.', NULL, '2026-04-04 20:37:25', 1, 'CHiPS', 17, '2026-04-06 10:38:02'),
(8, 1, 16, 'Pre-bid query responses for EoI Ref. No. EoI/EMPL/CSF/AMP II/SPMU have been published.', NULL, '2026-04-08 10:21:24', 1, 'CHiPS', 16, '2026-04-08 13:01:25'),
