INSERT INTO `communication_tbl` (`recordid`, `requestid`, `fromuserid`, `message`, `message_file`, `creationdate`, `isclosed`, `closedby`, `subuserid`, `vendorids`, `departmentid`) VALUES
(1, 121, 14, 'With reference to providing consultancy services through EOI for the Project Management Unit (PMU), the demand letter of this department, as desired by you, is enclosed herewith and forwarded for necessary action.', 'uploads/message_files/iOj5ooA6sD8YoG2QDt7CVmV3XzKabGst4YS622so.pdf', '2026-02-25 16:14:53', 1, 0, NULL, NULL, 2),
(2, 114, 1, 'The last date for submission of the Expression of Interest has been completed, however, no proposals have been received from any firms against the said EoI. You are requested to kindly guide us regarding the further course of action in this matter.', NULL, '2026-03-03 13:35:31', 1, 0, NULL, NULL, 66),
(3, 122, 1, 'Please find attached the Demand Notes for Advance Payment for availing the Consultancy Services.', 'uploads/message_files/s4ksQjt6PKFyXWHytLCYJLviwBitfCyFyNTGe2vV.pdf', '2026-03-06 12:13:40', 1, 0, NULL, NULL, 75),
(5, 120, 1, 'Please find attached herewith the Demand Notes for Advance Payment for availing Consultancy services.', 'uploads/message_files/gM3T2bHJ3WOwG9vmK3k65p9o4Ur4c9NyxnGMrpiX.pdf', '2026-03-06 12:15:55', 1, 0, NULL, NULL, 73),
(6, 119, 1, 'Please find attached herewith the Demand Notes for Advance Payment for availing Consultancy Services', 'uploads/message_files/VelDHVgxThALaVlFWGEt6J21TjZkr3Sz88kxgBjh.pdf', '2026-03-06 16:30:58', 1, 0, NULL, NULL, 71),
(7, 122, 1, 'Please find attached the Demand Notes for Advance Payment for availing the Consultancy Services.', 'uploads/message_files/AVJOeLWK86pJGVazTMOais8FoF9JTX3wSqCshRL9.pdf', '2026-03-07 08:02:24', 1, 0, NULL, NULL, 75),
(8, 132, 1, 'Draft EoI required', NULL, '2026-03-16 17:39:29', 1, 0, NULL, NULL, 32),
(9, 132, 60, 'Please find attached Draft EoI', 'uploads/message_files/xjxITDKeaqSPL9qi8mPTOnEo9soZR8IUtO65Slxo.docx', '2026-03-17 12:35:48', 1, 0, NULL, NULL, 32),
(10, 118, 99, 'Please schedule the interview on date 07 April 2026, starting at 11 AM.', NULL, '2026-03-27 10:43:15', 1, 0, NULL, NULL, 68),
(11, 121, 14, 'Kindly extend the last date for submission of proposals by 7 days to 3 April 2026.', NULL, '2026-03-27 13:13:26', 1, 0, NULL, NULL, 2),
(12, 120, 109, 'Kindly reschedule the interview and presentation date from 30.03.2026 to 01.04.2026 at 12-00 PM', 'uploads/message_files/zbFamGD7qoqw2v6b1ap9iGUzmwedv0gQp3YKeM2h.pdf', '2026-03-27 18:07:08', 1, 0, NULL, NULL, 73),
