(486, 0, 116, 3750, 0, NULL, NULL, NULL, NULL, '2025-11-18', NULL, 0, 'Pending', NULL, NULL, 0, 0, NULL, 1, 6, 2, '', '(7+ years)', 0, '<ul>\r\n<li>Relevant Graduation/MBA (or equivalent)</li>\r\n<li>7+ years of relevant experience&nbsp;</li>\r\n</ul>', 'FULL TIME', 0, 12, '<p>Operations and Procurement Specialist&nbsp;</p>', 159, 378000.00, 378000.00, 0.00, 0.00, 18.00, 777600.00, 5.00, 254880.00, 5352480.00, 0, NULL, 0, 2, NULL, NULL, 0, NULL, 0, 0),
(487, 0, 116, 3751, 543, 'CSO232', 'Sandeep Kumar Halder', '9691260679', 'sandeep.halder@in.ey.com', '2025-11-18', '2025-12-01', 0, 'Active', NULL, NULL, 1, 0, NULL, 1, 6, 3, '', '(5+ years)', 0, '<ul>\r\n<li>Relevant Graduation/MBA (or equivalent)</li>\r\n<li>5+ years of relevant experience&nbsp;</li>\r\n</ul>', 'FULL TIME', 0, 12, '<p>MIS and Monitoring Specialist&nbsp;</p>', 160, 336000.00, 336000.00, 0.00, 0.00, 18.00, 691200.00, 5.00, 226560.00, 4757760.00, 0, NULL, 0, 2, NULL, NULL, 0, NULL, 0, 0),
(488, 0, 117, 3742, 485, 'CSO181', 'Ashwani Yadu', '8770826464', NULL, '2026-04-07', '2026-04-15', 0, 'Active', NULL, NULL, 1, 0, NULL, 1, 3, 1, '', '(10+ years)', 0, '<p>Governance Sector</p>', 'FULL TIME', 0, 12, '<p>Focus- Strategy, policy, and high-level administration</p>\r\n<ol>\r\n<li>Strategic roadmap- Develop a 3-5 year digital transformation vision for the corporation.</li>\r\n<li>Policy formulation- Draft internal policies regarding procurement, human resources, and corporate ethics.</li>\r\n<li>Institutional Strengthening- Identify gaps in organizational structure and recommend capacity-building measures.</li>\r\n<li>Regulatory compliance- Ensure all corporate actions align with the Chhattisgarh Excise Act and State Government mandates.</li>\r\n<li>Inter-Departmental Liaison- Act as the primary point of contact between CSMCL and the Department of IT/ Finance.</li>\r\n<li>Performance Audits- Conduct periodic reviews of departmental KPIs and suggest corrective actions.</li>\r\n<li>Resource Optimization- Analyze budget utilization and suggest ways to reduce operational overheads.</li>\r\n<li>Crisis Management- Develop protocols for handling administrative or legal contingencies.</li>\r\n<li>CSR Framework- design and oversee the implementation of Corporate Social Responsibility initiatives.</li>\r\n<li>Board Support- Prepare strategic briefs and presentations for Board of Directors&rsquo; meetings.</li>\r\n</ol>', 143, 420000.00, 420000.00, 0.00, 0.00, 18.00, 864000.00, 5.00, 283200.00, 5947200.00, 0, NULL, 0, 2, NULL, NULL, 0, NULL, 0, 0),
(489, 0, 117, 3743, 0, 'CSO182', 'Rahul Pragalbh', '7987784570', NULL, '2026-04-07', '2026-06-01', 0, 'Active', NULL, NULL, 0, 0, NULL, 1, 1, 2, '', '(7+ years)', 0, '<p>IT&nbsp;</p>', 'FULL TIME', 0, 12, '<p>Focus- Enterprise Architecture and Technical Leadership</p>\r\n<ol>\r\n<li>IT Infrastructure Design- Architect the server, network, and loud environment for the entire corporation.</li>\r\n<li>Tech Stack Selection- Decide on the programming languages, databases, and frameworks for new software projects.</li>\r\n<li>Security Governance- Implement high-level data encryption and cyber security frameworks (ISO 2700 standards).</li>\r\n<li>System Integration-Ensure seamless communication between inventory systems, retails POS, and financial accounting software.</li>\r\n<li>Technical Budgeting- Prepare estimates for hardware procurement and software licensing.</li>\r\n<li>Disaster Recovery- Design a robust Business Continuity Plan (BCP) and off-site data backup strategy.</li>\r\n<li>Scalability Planning- Ensure IT systems can handle peak loads during festive seasons or expansion.</li>\r\n<li>Vendor Management- Lead technical evaluations of RFPs and oversee the performance of external IT agencies.</li>\r\n<li>Standardization- Set coding and documentation standards for all internal and outsourced IT projects.</li>\r\n<li>Emerging Tech Adoption- Explore the use of Blockchain for supply cain transparency or AI for demand forecasting.</li>\r\n</ol>', 134, 378000.00, 378000.00, 0.00, 0.00, 18.00, 777600.00, 5.00, 254880.00, 5352480.00, 0, NULL, 0, 2, NULL, NULL, 0, NULL, 0, 0),
(490, 0, 117, 3744, 486, 'CSO183', 'Lavesh kale', '8130826528', 'lavesh.kale@in.ey.com', '2026-04-07', '2026-04-15', 0, 'Active', NULL, NULL, 1, 0, NULL, 1, 1, 3, '', '(5+ years)', 0, '<p>IT</p>', 'FULL TIME', 0, 12, '<p>Focus- Project Management and Systems Implementation</p>\r\n<ol>\r\n<li>Project Lifecycle Management- Oversee daily progress of software modules from design to UAT (User Acceptance Testing).</li>\r\n<li>Database Management- Supervise the integrity and optimization of large-scale SQL/NoSQL databases.</li>\r\n<li>Software Quality Assurance- Establish rigorous testing protocols to eliminate bugs before system deployment.</li>\r\n<li>Dashboard Development- Create real-time MIS (Management Information System) dashboards for senior management.</li>\r\n<li>Supply Chain Digitization- Implement end-to-end tracking of stock from distilleries to retail outlets.</li>\r\n<li>API Management- Manage integrations with third-party payment gateways and bank systems.</li>\r\n<li>Hardware Maintenance- Oversee the upkeep of data centres, POS machines, and biometric systems.</li>\r\n<li>Incident Response- Lead the technical team in resolving server downtimes or system crashes.</li>\r\n<li>Data Migration- Supervise the secure the secure transfer of legacy data into new digital platforms.</li>\r\n<li>SLA Monitoring- Track Service Level Agreements of IT vendors to ensure 99.9% system uptime.</li>\r\n</ol>', 135, 336000.00, 336000.00, 0.00, 0.00, 18.00, 691200.00, 5.00, 226560.00, 4757760.00, 0, NULL, 0, 2, NULL, NULL, 0, NULL, 0, 0),
(491, 0, 117, 3745, 487, 'CSO184', 'B sameer', '9685331215', 'b.sameer@in.ey.com', '2026-04-07', '2026-04-15', 0, 'Active', NULL, NULL, 1, 0, NULL, 1, 3, 4, '', '(3+ years)', 0, '<p>Understanding of Excise / taxation/ Supply chain/ Government processes preferred.</p>', 'FULL TIME', 0, 12, '<p>Focus- Operations, Documentation, and Implementation</p>\r\n<ol>\r\n<li>Operational Monitoring- Track the daily implementation of government schemes and corporate directives.</li>\r\n<li>Standard Operating Procedures (SOPs)- Create detailed manuals for retail shop operations and warehouse management.</li>\r\n<li>GrievanceRedressal- Manage the system for handling complaints from citizens or stakeholders.</li>\r\n<li>Field Coordination- Visit field offices/ retail points to ensure digital systems are being used correctly.</li>\r\n<li>Documentation &amp; reporting- Maintain all official files, meeting minutes, and progress reports for CHiPS.</li>\r\n<li>Training Coordination- Organize training sessions for ground staff on new digital apps and compliance tools.</li>\r\n<li>Data Validation- Verify the accuracy of data entered at the field before it reaches the main database.</li>\r\n<li>Transparency Initiatives- Ensure that all public-facing information is updated on the corporate portal regularly.</li>\r\n<li>Procurement Assistance- Help in the preparation of tender documents and technical specifications for office equipment.</li>\r\n<li>Administrative Coordination- Facilitate the logistical needs of the consulting team and liaison with the CEO&rsquo;s office.</li>\r\n</ol>', 146, 288750.00, 288750.00, 0.00, 0.00, 18.00, 594000.00, 5.00, 194700.00, 4088700.00, 0, NULL, 0, 2, NULL, NULL, 0, NULL, 0, 0),
(492, 0, 118, 3752, 0, NULL, 'Alakh Shukla', NULL, NULL, '2025-07-23', '2025-11-20', 0, 'Extended', NULL, NULL, 1, 0, NULL, 1, 3, 2, '', '(7+ years)', 0, '<ol>\r\n<li>Education and Certifications\r\n<ul>\r\n<li>BE / BTech any specialization</li>\r\n<li>MBA/ PGDM/ MS</li>\r\n<li>PRINCE2 or PMP certified</li>\r\n</ul>\r\n</li>\r\n<li>5+ years of procurement experience in the government and public sector domain</li>\r\n<li>5+ years of experience in working with state/central government projects</li>\r\n<li>Preferred procurement experience for contact center projects in the &nbsp;government and public sector domain</li>\r\n<li>Preferred experience in managing bid process management of at least 100 crore project in the government and public sector domain</li>\r\n<li>Experience of managing 3 or more large e-governance / IT projectsfor the governmentin the capacity of team lead / project lead / project manager</li>\r\n</ol>', 'FULL TIME', 0, 6, '<p>Procurement Specialist</p>', 48, 360000.00, 360000.00, 0.00, 0.00, 18.00, 388800.00, 5.00, 127440.00, 2676240.00, 1, NULL, 0, 2, NULL, NULL, 0, NULL, 0, 0),
(493, 0, 118, 3753, 0, NULL, 'Anoop Kumar Verma', NULL, NULL, '2025-07-23', '2025-08-27', 0, 'Extended', NULL, NULL, 1, 0, NULL, 1, 3, 3, '', '(5+ years)', 0, '<ol>\r\n<li>Education-BE / BTech any specialization</li>\r\n<li>5+ years of experience in the government and public sector domain</li>\r\n<li>Experience of working on at least 2 contact center projects/grievance redressalproject</li>\r\n<li>PreferredExperience of working on at least 1 CM Helpline Project</li>\r\n</ol>', 'FULL TIME', 0, 6, '<p>CM Helpline Expert</p>', 49, 320000.00, 320000.00, 0.00, 0.00, 18.00, 345600.00, 5.00, 113280.00, 2378880.00, 1, NULL, 0, 2, NULL, NULL, 0, NULL, 0, 0),
(494, 0, 118, 3754, 0, NULL, 'Rakesh Kumar', NULL, NULL, '2025-07-23', '2025-08-27', 0, 'Extended', NULL, NULL, 1, 0, NULL, 1, 3, 3, '', '(5+ years)', 0, '<ol>\r\n<li>Education-BE / BTech any specialization</li>\r\n<li>5+ years of contact center experience</li>\r\n<li>3+ years of experience in working withstate/central government projects</li>\r\n<li>Experienceofdefining the standard operating procedure (SOP) for contact centers</li>\r\n<li>Experience of managing call center operations 6. Preferred contact center certification</li>\r\n</ol>', 'FULL TIME', 0, 6, '<p>Contact Center Expert</p>', 49, 320000.00, 320000.00, 0.00, 0.00, 18.00, 345600.00, 5.00, 113280.00, 2378880.00, 1, NULL, 0, 2, NULL, NULL, 0, NULL, 0, 0),
(495, 0, 119, 3755, 0, NULL, NULL, NULL, NULL, '2025-12-30', NULL, 0, 'Pending', NULL, NULL, 0, 0, NULL, 1, 4, 2, '', '(7+ years)', 0, '<ul>\r\n<li>M. Tech / ME in Water Resource/ Hydrology.</li>\r\n<li>At least 12 years of experience in water resources sector</li>\r\n<li>Must have experience of handling at least 2 similar projects as Hydrologic Modeller/ Hydraulic Modeller related to Inflow Forecasting/Flood Forecasting/ Dam Break Modelling/Design Flood review.&nbsp;</li>\r\n</ul>', 'FULL TIME', 0, 12, '<p>Team Leader cum strategy Expert&nbsp;</p>', 149, 378000.00, 378000.00, 0.00, 0.00, 18.00, 777600.00, 5.00, 254880.00, 5352480.00, 0, NULL, 0, 2, '2025-12-30', '2026-12-29', 0, NULL, 0, 0),
(496, 0, 119, 3756, 0, NULL, NULL, NULL, NULL, '2025-12-30', NULL, 0, 'Pending', NULL, NULL, 0, 0, NULL, 1, 3, 4, '', '(3+ years)', 0, '<ul>\r\n<li>Post-graduate degree in Civil, Sociology, mass communication, social sciences, management, social work, or any other relevant field.</li>\r\n<li>At least 5 years of experience in capacity building of stakeholders on government programs, developing education and IEC material, and collaterals&nbsp;</li>\r\n</ul>', 'PART TIME', 0, 9, '<p>Capacity building and Communit y Engageme nt Officer&nbsp;</p>', 146, 288750.00, 288750.00, 0.00, 0.00, 18.00, 445500.00, 5.00, 146025.00, 3066525.00, 0, NULL, 0, 2, '2025-12-30', '2026-09-29', 0, NULL, 0, 0);
