(502, 0, 120, 3762, 517, 'CSO216', 'Manish Narayan sandilya', '9628423666', 'manishsandilya@kpmg.com', '2025-12-30', '2026-02-02', 0, 'Active', NULL, NULL, 1, 0, NULL, 1, 4, 2, '', '(7+ years)', 0, '<ul>\r\n<li>&nbsp;B. Tech / BE (Civil Engineering) with MBA or M. Tech / M.E.in Hydrology, Hydraulic/ Water Resources Engineering/ equivalent having fair knowledge of Water Resource Sector.</li>\r\n<li>At least 10 years of working experience in water sector.</li>\r\n<li>Must have experience of handling at least one project as a Team Leader/ Dy. Team leader / Project Manager.</li>\r\n<li>Proven skills in technical report writing is required.&nbsp;</li>\r\n</ul>', 'FULL TIME', 0, 12, '<p>Team Leader cum Ground Water Expert &nbsp;</p>', 149, 378000.00, 378000.00, 0.00, 0.00, 18.00, 777600.00, 5.00, 254880.00, 5352480.00, 0, NULL, 0, 2, '2025-12-30', '2026-12-29', 0, NULL, 0, 0),
(503, 0, 120, 3763, 0, 'CSO217', 'Aritra Saha', '9679728217', 'aritrasaha2@kpmg.com', '2025-12-30', '2026-01-29', 0, 'Active', NULL, NULL, 0, 0, NULL, 1, 3, 4, '', '(3+ years)', 0, '<ul>\r\n<li>BE/B. Tech in IT/Computer Science/MCA from reputed institution</li>\r\n<li>At least 5 years of experience, including 3+ years in government programs/PMUs project management or digital platforms.</li>\r\n<li>Proficient in IT systems, web portals, dashboards, and reporting tools, with strong skills in Power BI, MS Excel, and MS PowerPoint.</li>\r\n<li>Experience managing MIS, dashboards, data analysis etc.&nbsp;</li>\r\n</ul>', 'FULL TIME', 0, 12, '<p>MIS and Data Analysis Specialist&nbsp;</p>', 146, 288750.00, 288750.00, 0.00, 0.00, 18.00, 594000.00, 5.00, 194700.00, 4088700.00, 0, NULL, 0, 2, '2025-12-30', '2026-12-29', 0, NULL, 0, 0),
