(599, 0, 141, 3604, 787, 'CSO257', 'Lalit Mistry', '9819683809', 'lalitmistry@kpmg.com', '2026-05-12', '2026-05-12', 0, 'Active', NULL, NULL, 1, 0, NULL, 1, 5, 1, NULL, NULL, 0, '<ul>\r\n<li>Should be having a leadership position like Partner/CEO/MD of the organization.</li>\r\n<li>Should have minimum 20 years of experience in management consulting</li>\r\n<li>Should have extensive public sector experience both in India and abroad</li>\r\n<li>Should have done at least 5 engagements in healthcare in the last 5 years including international assignments.</li>\r\n<li>should have worked with ministry of health of family welfare/ state health department</li>\r\n</ul>', 'PART TIME', 0, 6, '<p>Project Director (Should be Available in Raipur as and when required)</p>', 57, 400000.00, 400000.00, 0.00, 0.00, 18.00, 439200.00, 5.00, 143960.00, 3023160.00, 0, NULL, 0, 2, '2026-05-12', '2026-11-11', 0, NULL, 0, 0),
(600, 0, 141, 3605, 790, 'CSO258', 'Dr Rohit Kumar Baghel', '7509284075', 'rohitbaghel@kpmg.com', '2026-05-12', '2026-08-03', 0, 'Active', NULL, NULL, 1, 0, NULL, 1, 5, 2, NULL, NULL, 0, '<ul>\r\n<li>Master’s degree or higher in health/Public Policy/Management</li>\r\n<li>12+ years of experience out of which 5 years of experience as a project/program lead in government consulting projects</li>\r\n<li>Experience of handling 5 government projects related to consulting/policy/advisory services</li>\r\n<li>Experience of leading and managing 2 projects in different departments of government of Chhattisgarh which involve Project/policy formulation, engagement with multiple government/private stakeholders, implementation and monitoring or program.</li>\r\n<li>A sound knowledge of overall procurement process, report writing and budgeting is required</li>\r\n<li>A candidate with the experience of working in multiple states with various state governments will be preferred.</li>\r\n</ul>', 'FULL TIME', 0, 6, '<p>Health Expert - Team lead (Full Time at Raipur)</p>', 58, 360000.00, 360000.00, 0.00, 0.00, 18.00, 395280.00, 5.00, 129564.00, 2720844.00, 0, NULL, 0, 2, '2026-05-12', '2026-11-11', 0, NULL, 0, 0),
(601, 0, 141, 3607, 791, 'CSO261', 'Ashish Kumar Singh', '9826911823', 'ashishsingh23@kpmg.com', '2026-05-12', '2026-06-25', 0, 'Active', NULL, NULL, 1, 0, NULL, 1, 5, 3, NULL, NULL, 0, '<ul>\r\n<li>Master in management/public policy/finance/Chartered Accountant</li>\r\n<li>At least 5+ years of work experience in procurement in Govt. Sector/PSUs Procurement Expert</li>\r\n<li>Relevant experience with government stakeholders in India (Health Insurance, Health Financing, Contracts, IEC, Procurement & PPP)</li>\r\n</ul>', 'PART TIME', 0, 6, '<p>Finance Expert (Full Time at Raipur)</p>', 59, 320000.00, 320000.00, 0.00, 0.00, 18.00, 351360.00, 5.00, 115168.00, 2418528.00, 0, NULL, 0, 2, '2026-05-12', '2026-11-11', 0, NULL, 0, 0),
(602, 0, 141, 3608, 788, 'CSO260', 'Dr. Nitin Patil', '7509284075', 'nitinpatil1@kpmg.com', '2026-05-12', '2026-06-23', 0, 'Active', NULL, NULL, 1, 0, NULL, 1, 5, 1, NULL, NULL, 0, '<ul>\r\n<li>Master\'s Master&rsquo;s degree in public health/ Epidemiology/Health Economics/ health management</li>\r\n<li>Professional with over 15 years of relevant experience and profound expertise in the field of health and health policy, this advisor will specialize in health systems strengthening, Health Insurance, Health Financing, Contracts, IEC, Procurement &amp; PPP and Healthcare. The role is pivotal, providing nuanced insights and strategic direction to steer the project towards the successful accomplishment of its objectives.</li>\r\n</ul>', 'PART TIME', 0, 6, '<p>Advisor (Should be Available in Raipur as and when required)</p>', 57, 400000.00, 400000.00, 0.00, 0.00, 18.00, 439200.00, 5.00, 143960.00, 3023160.00, 0, NULL, 0, 2, '2026-05-12', '2026-11-11', 0, NULL, 0, 0),
(603, 0, 141, 3609, 789, 'CSO259', 'Dr. Arun Gangadhar', '9567377788', 'arungangadharb@kpmg.com', '2026-05-12', '2026-06-08', 0, 'Active', NULL, NULL, 1, 0, NULL, 1, 5, 1, NULL, NULL, 0, '<ul>\r\n<li>Master\'s Master&rsquo;s degree in public health/ Epidemiology/Health Economics/ health management</li>\r\n<li>Professional with over 15 years of relevant experience and profound expertise in the field of health and health policy, this advisor will specialize in health systems strengthening, Health Insurance, Health Financing, Contracts, IEC, Procurement &amp; PPP and Healthcare. The role is pivotal, providing nuanced insights and strategic direction to steer the project towards the successful accomplishment of its objectives.</li>\r\n</ul>', 'PART TIME', 0, 6, '<p>Advisor (Should be Available in Raipur as and when required)</p>', 57, 400000.00, 400000.00, 0.00, 0.00, 18.00, 439200.00, 5.00, 143960.00, 3023160.00, 0, NULL, 0, 2, '2026-05-12', '2026-11-11', 0, NULL, 0, 0);
