(1, 86, 0, 0, 1, 2, 'Work Order for selection of consultants for Setting up of Program Management Unit (PMU) for Technical Support and Transaction Advisory Support for AMRUT 2.0.', '1009', '1009/ACEO/CHIPS/EMPL/PMU/SUDA/AMRUT2.0/2024', '2024-11-06', 'EOI/EMPL/CHiPS/PMU/SUDA/AMRUT 2.0/2024', '2025-07-01', '165081/CEO/CHiPS/Empanelment/ Consultancy Firms/2025 Raipur, dated 20/02/2025', '<ol>\r\n<li>1. Payment Term: CHiPS shall be charging 5% ofthe total project cost from the Department as Administration<br>Charge and as per Empanelment agreement<br>2. For Consultancy firm, Milestones Fixation &amp;Verification will be done by User Department<br>3. Payment (invoice) verification &amp; pass-for-Payment recommendation to consulting firms will be done by<br>User Department based on Milestone Achievement<br>4. Scope of work: As per EOI<br>5. Qualification and Experience of consultant: As per Empanelment agreement<br>6. Other Terms and Condition: As per Empanelment agreement<br>7. Man month rate beyond 16 February 2024 would be governed as per extended terms &amp; conditions mentioned<br>in Empanelment Agreement.<br>8. The above to extension will be valid for maximum period of one year subjected to changes in rate discovered<br>in any RFP floated by CHiPS in this regards, in future.</li>\r\n</ol>', 0, 0, 3, 0, '2025-10-28 19:03:17', 1, 'uploads/demandnotefiles/69jUaW42kejxa3DXI2gqP89fj6VnwA3e1H9Nd05o.pdf', NULL, NULL, NULL, 'uploads/workorderpayment/ibFCWSJpiUAtPVShoHd7TGUX6m6dWLejCYje7C0N.pdf', 0, 0, 194580000, 241084620, 11480220, 0, 241084620, 0, 18, 5, 1, 'Chhattisgarh Infotech Promotion Society', '225/ACEO/CHiPS/EMPL/CSF/2025/ Raipur Dated 13/05/2025', 'Add. Chief Executive Officer', 'M/s ERNST & YOUNG LLP, Raipur (C.G.)', 0, 0, 3, 'M/s ERNST & YOUNG LLP', '2025-10-28 21:05:42', 'uploads/signedorder/NX3eIyRcgFBZ72RTt8wWotJoVlitFwuzr6PnVjP7.pdf', '2025-03-25', NULL, 1, '2026-04-09 14:13:01', 0, 30, 36, 'Project Management Unit (PMU) for Technical Support and Transaction Advisory Support For AMRUT 2.0', 12, 1, 415, 'Assigned by M/s Ernst & Young LLP (CSF) on 06-05-2026, 02:06 PM', 0, NULL, NULL, 0, 0, NULL, 0, 0, NULL, NULL, 0, 0, 0, 0, 0, 0, 0, 1),
(2, 79, 0, 0, 2, 2, 'Work Order for Selection of PMU for Chhattisgarh Samvad, Public Relations Department', '1440', '1440/COO/CHIPS/EMPL/PMU/PRD/SAMVAD/2025', '2025-01-20', 'EOI/EMPL/CHIPS/PMU/PRD/Samvad/2025', '2025-07-01', '165081/CEO/CHiPS/Empanelment/ Consultancy Firms/2025 Raipur, dated 20/02/2025', '<ol>\r\n<li>Charge Payment and Term: as per CHiPS Empanelment shall be charging 5% of the total project cost fromthe Department as Administration agreement</li>\r\n<li>For Consultaney firm, Milestones Fixation &amp;Verification will be done by User Department</li>\r\n<li>Payment (invoice) verification &amp; pass-for-Payment recommendation to consulting firms will be done by User Department based on Milestone Achievement</li>\r\n<li>Scope of work: As per EOI</li>\r\n<li>Qualification and Experience of consultant: As per Empanelment agreement</li>\r\n<li>Taxes: Including Tax as applicable, currently 18% GST</li>\r\n<li>Other Terms and Condition: As per extended Empanelment agreement terms &amp; conditions</li>\r\n</ol>', 0, 0, 3, 0, '2025-10-28 19:30:44', 1, 'uploads/demandnotefiles/RbYJytfqhYdL33KynuIE1vMuf4pZggicKqgFE9AH.pdf', NULL, NULL, NULL, 'uploads/workorderpayment/YBJeiC3TpkCpiR3xYI1dTPHDAGUuGGfwJATlZClU.pdf', 0, 0, 14760000, 18287640, 870840, 0, 18287640, 0, 18, 5, 1, 'Chhattisgarh Infotech Promotion Society', '225/ACEO/CHiPS/EMPL/CSF/2025/ Raipur Dated 13/05/2025', 'Chief Operating Officer', 'M/s ERNST & YOUNG LLP, Raipur (C.G.)', 0, 0, 3, 'M/s ERNST & YOUNG LLP', '2025-10-28 21:05:47', 'uploads/signedorder/juvHdS5awhN0TdPTogT1i2dhFZvcdPMQKE5IzX1c.pdf', '2025-08-16', NULL, 1, '2026-02-10 18:14:42', 0, 29, 12, 'For selection of Project Management Unit (PMU) for Chhattisgarh Samvad, Public Relations Department', 11, 1, NULL, NULL, 0, NULL, NULL, 0, 0, NULL, 0, 0, NULL, NULL, 1864838.71, 335670.97, 2200509.68, 1, 1, 1, 1, 1),
