create database if not exists `empanelment`;

USE `empanelment`;


CREATE TABLE `area_tbl` (
  `areaid` int NOT NULL,
  `cityid` int NOT NULL DEFAULT '0',
  `areaname` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '',
  `createdby` int NOT NULL DEFAULT '0',
  `createdbyname` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '',
  `creationdate` datetime NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;


CREATE TABLE `block_tbl` (
  `blockid` int NOT NULL,
  `tehsilid` int NOT NULL DEFAULT '0',
  `blockname` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '',
  `blockcode` varchar(5) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '',
  `creationdate` datetime NOT NULL,
  `createdby` int NOT NULL DEFAULT '0'
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `category_tbl` (
  `categoryid` int NOT NULL,
  `parentcategoryid` int NOT NULL DEFAULT '0',
  `category` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '',
  `headingvalue` varchar(300) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  `displayorder` int NOT NULL DEFAULT '0',
  `categorystatus` int NOT NULL DEFAULT '0',
  `description` text CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  `metakeywords` text CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  `metadescription` text CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  `categoryicon` text CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  `icontype` text CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  `categorypage` text CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  `pagetype` text CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  `activity` text CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  `depthlevel` int NOT NULL DEFAULT '0',
  `createdby` int NOT NULL DEFAULT '0',
  `createdbyname` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '',
  `creationdate` datetime NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;


CREATE TABLE `chips_vendor_communication` (
  `messageid` bigint NOT NULL,
  `fromuserid` bigint DEFAULT NULL,
  `touserid` bigint DEFAULT NULL,
  `message` text CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci,
  `attachment` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `sent_on` datetime DEFAULT NULL,
  `isviewed` tinyint DEFAULT NULL,
  `sentby` enum('CHiPS','VENDOR') CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
  `viewedby` bigint DEFAULT NULL,
  `viewedon` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 CHECKSUM=1 COLLATE=utf8mb3_unicode_ci DELAY_KEY_WRITE=1 ROW_FORMAT=DYNAMIC;


CREATE TABLE `city_tbl` (
  `cityid` int NOT NULL,
  `stateid` int NOT NULL DEFAULT '0',
  `cityname` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '',
  `citycode` varchar(5) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '',
  `createdby` int NOT NULL DEFAULT '0',
  `creationdate` datetime NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `committee_member` (
  `memberid` int NOT NULL,
  `name` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `mobilenumber` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `designation` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `department` varchar(150) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `remark` varchar(300) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `userid` int DEFAULT '0',
  `usertype` enum('CHIPS','DEPARTMENT','PROJECT MANAGER') CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `creationdate` datetime DEFAULT NULL,
  `isdeleted` tinyint DEFAULT '0'
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `communication_status` (
  `id` bigint NOT NULL,
  `recordid` bigint DEFAULT NULL,
  `departmentid` int DEFAULT NULL,
  `vendorid` int DEFAULT NULL,
  `seen_status` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `seen_at` datetime DEFAULT NULL,
  `seen_by` bigint DEFAULT NULL,
  `message_for` enum('CHiPS','DEPARTMENT','PROJECT MANAGER','VENDOR') CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 CHECKSUM=1 COLLATE=utf8mb3_unicode_ci DELAY_KEY_WRITE=1 ROW_FORMAT=DYNAMIC;


CREATE TABLE `communication_tbl` (
  `recordid` bigint NOT NULL,
  `requestid` bigint DEFAULT '0',
  `fromuserid` bigint DEFAULT '0',
  `message` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci,
  `message_file` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `creationdate` datetime DEFAULT NULL,
  `isclosed` tinyint NOT NULL DEFAULT '0',
  `closedby` bigint NOT NULL DEFAULT '0',
  `subuserid` bigint DEFAULT NULL,
  `vendorids` text CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci,
  `departmentid` int DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 CHECKSUM=1 COLLATE=utf8mb3_unicode_ci DELAY_KEY_WRITE=1 ROW_FORMAT=DYNAMIC;


CREATE TABLE `departments` (
  `id` bigint NOT NULL,
  `user_id` int NOT NULL DEFAULT '0',
  `name` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '',
  `head_name` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '',
  `email` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '',
  `contact` varchar(15) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '',
  `office_location` varchar(250) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '',
  `isactive` tinyint NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` int NOT NULL DEFAULT '0'
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

CREATE TABLE `department_tbl` (
  `departmentid` int NOT NULL,
  `userid` int NOT NULL DEFAULT '0',
  `departmenttype` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '',
  `departmentname` varchar(150) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '',
  `shortname` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `projectname` varchar(150) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `designation` varchar(150) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `officialemail` varchar(150) DEFAULT NULL,
  `creationdate` datetime NOT NULL,
  `requestedby` int NOT NULL DEFAULT '0',
  `approvalstatus` tinyint NOT NULL DEFAULT '0',
  `actiondatetime` datetime DEFAULT NULL,
  `remark` varchar(150) DEFAULT NULL,
  `actiontakenby` int NOT NULL DEFAULT '0',
  `address` varchar(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `isprojectmanager` tinyint DEFAULT '0'
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

CREATE TABLE `deployment_detail` (
`admin` double
,`deployed_date` date
,`deployment_date` date
,`deployment_status` enum('Pending','Active','Released','Extended','Cancelled','Real')
,`deploymentid` int
,`email` varchar(100)
,`is_verified` tinyint
,`mobilenumber` varchar(10)
,`name` varchar(100)
,`operating` double
,`orderid` int
,`recordid` int
,`remuneration` double
,`tax` double
,`verified_by` int
,`verified_on` datetime
);

CREATE TABLE `designation_tbl` (
  `designationid` int NOT NULL,
  `designationname` varchar(150) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '',
  `aliasname` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '',
  `createdby` int NOT NULL DEFAULT '0',
  `createdbyname` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '',
  `creationdate` datetime NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `district_tbl` (
  `districtid` int NOT NULL,
  `stateid` int NOT NULL DEFAULT '0',
  `districtname` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '',
  `districtcode` varchar(5) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '',
  `creationdate` datetime NOT NULL,
  `createdby` int NOT NULL DEFAULT '0'
