  `payment_mode_id` bigint NOT NULL,
  `bank_account_id` bigint DEFAULT NULL,
  `transaction_no` varchar(100) DEFAULT NULL COMMENT 'UTR/Cheque/DD Number',
  `gross_received_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `taxable_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `gst_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `tds_tax_id` bigint DEFAULT NULL,
  `tds_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `gst_tds_tax_id` bigint DEFAULT NULL,
  `gst_tds_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `other_deduction` decimal(12,2) NOT NULL DEFAULT '0.00',
  `net_received_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `remarks` text,
  `attachment` varchar(255) DEFAULT NULL,
  `status` enum('Active','Cancelled','Invoiced') NOT NULL DEFAULT 'Active',
  `cancelled_by` bigint DEFAULT NULL,
  `cancelled_at` datetime DEFAULT NULL,
  `cancellation_reason` text,
  `created_by` bigint DEFAULT '0',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
