  `finance_remarks` text
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

DELIMITER $$
CREATE TRIGGER `insert_mpr_value` AFTER INSERT ON `mpr_attendance_summary` FOR EACH ROW BEGIN
    DECLARE total_net_salary DECIMAL(12,2);
    SELECT IFNULL(SUM(net_salary), 0)
    INTO total_net_salary
    FROM mpr_attendance_summary
    WHERE mpr_id = NEW.mpr_id;
    UPDATE mpr_tbl
    SET mpr_value = total_net_salary
    WHERE mpr_id = NEW.mpr_id;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `update_mpr_value` AFTER UPDATE ON `mpr_attendance_summary` FOR EACH ROW BEGIN
    DECLARE total_net_salary DECIMAL(12,2);
		DECLARE total_approved_salary DECIMAL(12,2);
    -- Use NEW.mpr_id in case it changed
    SELECT IFNULL(SUM(net_salary), 0),IFNULL(SUM(approved_salary), 0)
    INTO total_net_salary,total_approved_salary
    FROM mpr_attendance_summary
    WHERE mpr_id = NEW.mpr_id;
    UPDATE mpr_tbl
    SET mpr_value = total_net_salary,mpr_approved_value=total_approved_salary
    WHERE mpr_id = NEW.mpr_id;
END
$$
DELIMITER ;

