DROP TABLE IF EXISTS `deployment_detail`;

CREATE VIEW `deployment_detail`  AS SELECT `a`.`deploymentid` AS `deploymentid`, `a`.`orderid` AS `orderid`, `a`.`recordid` AS `recordid`, `a`.`name` AS `name`, `a`.`mobilenumber` AS `mobilenumber`, `a`.`email` AS `email`, `a`.`deployment_date` AS `deployment_date`, `a`.`deployed_date` AS `deployed_date`, `a`.`deployment_status` AS `deployment_status`, `a`.`is_verified` AS `is_verified`, `a`.`verified_by` AS `verified_by`, `a`.`verified_on` AS `verified_on`, `b`.`remuneration` AS `remuneration`, `b`.`operating` AS `operating`, `b`.`tax` AS `tax`, `b`.`admin` AS `admin` FROM (`eoi_resource_deployment` `a` join `eoi_request_detail` `b` on((`b`.`recordid` = `a`.`recordid`))) ;
DROP TABLE IF EXISTS `mpr_status`;

CREATE VIEW `mpr_status`  AS SELECT `f`.`userid` AS `userid`, `m`.`request_id` AS `request_id`, `m`.`order_id` AS `order_id`, `m`.`vendor_id` AS `vendor_id`, `m`.`mpr_id` AS `mpr_id`, `m`.`is_watched` AS `is_watched`, `m`.`mpr_number` AS `mpr_number` FROM ((`mpr_tbl` `m` join `eoi_request` `e` on((`m`.`request_id` = `e`.`requestid`))) join `department_tbl` `f` on((`f`.`userid` = `e`.`userid`))) WHERE (((`m`.`is_watched` = 0) OR (`m`.`mpr_status` <> 'Verified')) AND (`m`.`submission_date` is not null)) ;
DROP TABLE IF EXISTS `order_eoi`;

CREATE VIEW `order_eoi`  AS SELECT `a`.`orderid` AS `orderid`, `a`.`requestid` AS `requestid`, `a`.`orderno` AS `orderno`, `a`.`ordernumber` AS `ordernumber`, `a`.`orderdate` AS `orderdate`, `a`.`vendorid` AS `vendorid`, `a`.`totalremuneration` AS `totalremuneration`, `a`.`totalbudget` AS `totalbudget`, `a`.`totaladmincharge` AS `totaladmincharge`, `a`.`totaloperatingcost` AS `totaloperatingcost`, `a`.`workorderamount` AS `workorderamount`, `a`.`operatingmargin` AS `operatingmargin`, `a`.`tax` AS `tax`, `a`.`admincharge` AS `admincharge`, `a`.`workorderduedate` AS `workorderduedate`, `a`.`nextreminderdate` AS `nextreminderdate`, `b`.`userid` AS `userid`, `b`.`eoinumber` AS `eoinumber`, `b`.`projecttitle` AS `projecttitle`, `b`.`projectduration` AS `projectduration`, `b`.`eoistatus` AS `eoistatus` FROM (`eoi_work_order` `a` join `eoi_request` `b` on((`b`.`requestid` = `a`.`requestid`))) WHERE (`a`.`orderno` <> '') ;
DROP TABLE IF EXISTS `order_eoi_department_vendor`;

CREATE VIEW `order_eoi_department_vendor`  AS SELECT `a`.`orderid` AS `orderid`, `a`.`requestid` AS `requestid`, `a`.`orderno` AS `orderno`, `a`.`ordernumber` AS `ordernumber`, `a`.`orderdate` AS `orderdate`, `a`.`vendorid` AS `vendorid`, `a`.`totalremuneration` AS `totalremuneration`, `a`.`totalbudget` AS `totalbudget`, `a`.`totaladmincharge` AS `totaladmincharge`, `a`.`totaloperatingcost` AS `totaloperatingcost`, `a`.`workorderamount` AS `workorderamount`, `a`.`operatingmargin` AS `operatingmargin`, `a`.`tax` AS `tax`, `a`.`admincharge` AS `admincharge`, `a`.`workorderduedate` AS `workorderduedate`, `a`.`nextreminderdate` AS `nextreminderdate`, `b`.`userid` AS `userid`, `b`.`eoinumber` AS `eoinumber`, `b`.`projecttitle` AS `projecttitle`, `b`.`projectduration` AS `projectduration`, `b`.`eoistatus` AS `eoistatus`, `c`.`companyname` AS `companyname`, `c`.`officelocation` AS `officelocation`, `d`.`departmentname` AS `departmentname`, `d`.`address` AS `address` FROM (((`eoi_work_order` `a` join `eoi_request` `b` on((`b`.`requestid` = `a`.`requestid`))) join `vendor_tbl` `c` on((`c`.`vendorid` = `a`.`vendorid`))) join `department_tbl` `d` on((`d`.`userid` = `b`.`userid`))) WHERE (`a`.`orderno` <> '') ;
DROP TABLE IF EXISTS `pending_deployment`;

CREATE VIEW `pending_deployment`  AS SELECT DISTINCT `w`.`orderid` AS `orderid`, `w`.`ordernumber` AS `ordernumber`, `w`.`vendorid` AS `vendorid` FROM (`eoi_work_order` `w` join `eoi_resource_deployment` `d` on((`d`.`orderid` = `w`.`orderid`))) WHERE ((`w`.`isActiveOrder` = 1) AND (`w`.`isExtended` = 0) AND (`d`.`deployment_status` = 'Pending') AND (`d`.`isExtended` = 0) AND (`d`.`is_verified` = 0) AND (`w`.`workorderduedate` > curdate())) ;
DROP TABLE IF EXISTS `pending_deployment_verification`;

CREATE VIEW `pending_deployment_verification`  AS SELECT DISTINCT `b`.`orderid` AS `orderid`, `b`.`ordernumber` AS `ordernumber`, `c`.`userid` AS `userid`, `a`.`deployed_date` AS `deployed_date`, `a`.`deployment_status` AS `deployment_status` FROM ((`eoi_resource_deployment` `a` join `eoi_work_order` `b` on((`b`.`orderid` = `a`.`orderid`))) join `eoi_request` `c` on((`c`.`requestid` = `b`.`requestid`))) WHERE ((`a`.`deployment_status` = 'Pending') AND (`a`.`deployed_date` is not null)) ;
DROP TABLE IF EXISTS `pending_resumes`;

CREATE VIEW `pending_resumes`  AS SELECT `a`.`floatid` AS `floatid`, `a`.`requestid` AS `requestid`, `c`.`eoinumber` AS `eoinumber`, `b`.`participationid` AS `participationid`, `b`.`vendorid` AS `vendorid`, `a`.`signedcopyofeoi` AS `signedcopyofeoi`, `a`.`subuserid` AS `subuserid` FROM ((`eoi_request_floated` `a` join `eoi_request_participation` `b` on((`a`.`floatid` = `b`.`floatid`))) join `eoi_request` `c` on((`a`.`requestid` = `c`.`requestid`))) WHERE ((`a`.`signedcopyofeoi` is null) AND (`c`.`deadlinedate` > now())) ;
DROP TABLE IF EXISTS `regularisation`;

CREATE VIEW `regularisation`  AS SELECT `a`.`mpr_id` AS `mpr_id`, `a`.`order_id` AS `order_id`, `a`.`vendor_id` AS `vendor_id`, `a`.`mpr_number` AS `mpr_number`, `a`.`report_month` AS `report_month`, `a`.`mpr_month` AS `mpr_month`, `a`.`mpr_year` AS `mpr_year`, `a`.`submission_date` AS `submission_date`, `b`.`summary_id` AS `summary_id`, `b`.`deployment_id` AS `deployment_id`, `b`.`net_salary` AS `net_salary`, `b`.`deduction` AS `deduction`, `b`.`approved_salary` AS `approved_salary`, `b`.`remarks` AS `remarks`, `b`.`deduction_file` AS `deduction_file`, `b`.`mpr_file` AS `mpr_file`, `b`.`attendance_file` AS `attendance_file`, `b`.`supporting_file` AS `supporting_file`, `b`.`mpr_remark` AS `mpr_remark` FROM (`mpr_tbl` `a` join `mpr_attendance_summary` `b` on((`b`.`mpr_id` = `a`.`mpr_id`))) WHERE (`b`.`isFlaged` = 1) ;
DROP TABLE IF EXISTS `resource_counting`;

CREATE VIEW `resource_counting`  AS SELECT `a`.`categoryid` AS `categoryid`, count(0) AS `total_count` FROM (`eoi_work_order` `a` left join `eoi_resource_deployment` `b` on((`b`.`orderid` = `a`.`orderid`))) WHERE ((`a`.`isCancelled` = 0) AND (`a`.`isActiveOrder` = 1) AND (`b`.`deployment_status` = 'Active') AND (cast(`a`.`workorderduedate` as date) >= curdate())) GROUP BY `a`.`categoryid` ;
DROP TABLE IF EXISTS `user_menu_permission`;

CREATE VIEW `user_menu_permission`  AS SELECT `a`.`menuid` AS `menuid`, `a`.`mastermenu` AS `mastermenu`, `c`.`actionid` AS `actionid`, `c`.`actionname` AS `actionname` FROM ((`mainmenu_tbl` `a` left join `menu_mapping` `b` on((`b`.`menuid` = `a`.`menuid`))) left join `menu_action` `c` on((`c`.`actionid` = `b`.`actionid`))) WHERE ((`a`.`parentid` <> 0) OR (`a`.`menuurl` <> '')) ORDER BY `a`.`menuid` ASC, `c`.`displayorder` ASC ;
DROP TABLE IF EXISTS `vendor_resource_counting`;

CREATE VIEW `vendor_resource_counting`  AS SELECT `a`.`vendorid` AS `vendorid`, count(0) AS `total_count` FROM (`eoi_work_order` `a` left join `eoi_resource_deployment` `b` on((`b`.`orderid` = `a`.`orderid`))) WHERE ((`a`.`isActiveOrder` = 1) AND (`b`.`isExtended` = 0) AND (`a`.`isCancelled` = 0) AND (`b`.`deployment_status` = 'Active') AND (cast(`a`.`workorderduedate` as date) >= curdate())) GROUP BY `a`.`vendorid` ;


ALTER TABLE `remuneration_rate_list`
  ADD CONSTRAINT `remuneration_rate_list_category` FOREIGN KEY (`categoryid`) REFERENCES `jobcategory_tbl` (`categoryid`);
COMMIT;

